def all_sessions(self) -> list[tuple[str, SessionStatus]]:
    """Snapshot every started session in session registration order.

    The order is the order sessions were first opened in the current
    process: a session torn down by :meth:`reset_session` or
    :meth:`remove` disappears entirely, and a later re-open takes its
    new position rather than the old one. Each snapshot is computed on
    the fly; nothing is created, reordered or recorded.
    """

    return [
        (resource_id, self._status_of(session))
        for resource_id, session in self._sessions.items()
    ]

